INSERT INTO `contentdb`.`novel` (`novel_id`, `author_id`, `collected_count`, `cover_url`, `create_time`, `introduction`, `novel_name`, `original_novel_id`, `recommend_count`, `score`, `status`, `total_price`, `total_word_count`) VALUES
('32', '12', '4', 'https://picsum.photos/seed/novel32/300/400', '2026-06-06 10:00:00', '如意是长安城里最出名的绣娘，一针一线，绣尽人间百态。', '如意姑娘的', '-1', '5', '4.5', '连载', '2104', '30800'),
('33', '6', '2', 'https://picsum.photos/seed/novel33/300/400', '2026-06-04 10:00:00', '一封封没有署名的情书，从校园寄到职场，写给那个笨拙温柔的鼹鼠先生。', '写给鼹鼠先生的情', '-1', '1', '3.8', '连载', '2038', '30272'),
('34', '11', '5', 'https://picsum.photos/seed/novel34/300/400', '2026-06-02 10:00:00', '九卿之首谢云琅权倾朝野，唯独在她面前，卸下所有锋芒。', '问九卿', '-1', '4', '5.0', '完结', '3154', '38094'),
('35', '12', '4', 'https://picsum.photos/seed/novel35/300/400', '2026-05-31 10:00:00', '将门嫡女昭昭重生归来，这一世，她要护住满门忠烈。', '昭娇', '-1', '3', '3.8', '连载', '2378', '31568'),
('36', '11', '3', 'https://picsum.photos/seed/novel36/300/400', '2026-05-29 10:00:00', '岁岁年年花相似，唯有你，是我岁时里的来仪。', '岁时来仪', '-1', '2', '4.3', '完结', '2017', '27427'),
('37', '1', '2', 'https://picsum.photos/seed/novel37/300/400', '2026-05-27 10:00:00', '一柄断剑出鞘，少年萧尘自北境崛起，剑锋所指，苍穹为之震颤。', '剑破苍穹', '-1', '1', '4.5', '连载', '4792', '49308'),
('38', '2', '3', 'https://picsum.photos/seed/novel38/300/400', '2026-05-25 10:00:00', '神秘医道传人龙飞归隐都市，一双回春妙手，搅动风云。', '都市龙医', '-1', '3', '4.5', '连载', '3160', '40822'),
('39', '11', '6', 'https://picsum.photos/seed/novel39/300/400', '2026-05-23 10:00:00', '深空探测船失联四十年后突然返航，船上的人，一个都没老。', '深空彼岸', '-1', '3', '4.0', '连载', '4485', '43570'),
